import { useEffect, useRef, useState } from 'react';
import webpPoster from '../assets/video/backgroundVideoPoster.webp';
import pngPoster from '../assets/video/backgroundVideoPoster.png';
import webpPosterMobile from '../assets/video/backgroundVideoPosterMobile.webp';
import pngPosterMobile from '../assets/video/backgroundVideoPosterMobile.png';
import backgroundVideo from '../assets/video/backgroundVideo.webm';

const canLoadHeroVideo = () => {
  if (typeof window === 'undefined') return false;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return false;
  if (navigator.connection?.saveData) return false;
  return true;
};

const VideoSection = () => {
  const videoRef = useRef(null);
  const [videoReady, setVideoReady] = useState(false);

  useEffect(() => {
    if (!canLoadHeroVideo()) return undefined;

    let cancelled = false;
    const video = videoRef.current;
    if (!video) return undefined;

    const startVideo = () => {
      if (cancelled) return;
      video.muted = true;
      video.defaultMuted = true;
      video.playsInline = true;
      video.setAttribute('muted', '');
      video.setAttribute('playsinline', '');
      video.src = backgroundVideo;
      video.load();

      const tryPlay = () => {
        const play = video.play();
        if (play && typeof play.then === 'function') {
          play
            .then(() => {
              if (!cancelled) setVideoReady(true);
            })
            .catch(() => {
              // Autoplay blocked — keep poster visible.
            });
        }
      };

      if (video.readyState >= 2) {
        tryPlay();
      } else {
        video.addEventListener('loadeddata', tryPlay, { once: true });
      }
    };

    const idleId =
      'requestIdleCallback' in window
        ? window.requestIdleCallback(startVideo, { timeout: 1200 })
        : window.setTimeout(startVideo, 400);

    return () => {
      cancelled = true;
      if ('requestIdleCallback' in window) {
        window.cancelIdleCallback(idleId);
      } else {
        window.clearTimeout(idleId);
      }
    };
  }, []);

  return (
    <section className="header-element-section">
      <picture className={`header-poster${videoReady ? ' is-hidden' : ''}`}>
        <source media="(max-width: 768px)" type="image/webp" srcSet={webpPosterMobile} />
        <source media="(max-width: 768px)" type="image/png" srcSet={pngPosterMobile} />
        <source type="image/webp" srcSet={webpPoster} />
        <source type="image/png" srcSet={pngPoster} />
        <img
          src={webpPoster}
          alt="Uguņošana pie ūdens — Tropiks AZ"
          className="header-element"
          fetchpriority="high"
        />
      </picture>

      <video
        ref={videoRef}
        className={`header-element header-video${videoReady ? ' is-ready' : ''}`}
        muted
        loop
        playsInline
        autoPlay
        preload="metadata"
        role="presentation"
        tabIndex={-1}
        onFocus={(event) => event.currentTarget.blur()}
      />

      <div className="header-element-content">
        <p className="header-brand">TROPIKS AZ</p>
        <h1 className="header-element-text">
          Noslēdz svētkus
          <br />
          ar <span>UGUŅOŠANU!</span>
        </h1>
        <a href="#katalogs" className="header-cta">
          Skatīt katalogu
        </a>
      </div>
    </section>
  );
};

export default VideoSection;
